//! The compile vectors: the guest's DDL is BYTE-IDENTICAL
//! to the CLI's `surform build` on the same document.
//!
//! Strategy (documented in the crate README): the expected DDL is
//! PINNED — `tests/goldens/<name>.ddl` files generated by the real
//! `surform build` binary at unit time (from the repo root:
//! `cargo run --bin surform -- build tests/fixtures/<name>.surdl >
//! surform-surrealism/tests/goldens/<name>.ddl`; the migration
//! snippets below live at `docs/examples/<name>.surdl` instead of
//! `tests/fixtures/` — same recipe, that path shape).
//! The guest's `compile` runs the identical pipeline through the same
//! path-depended core (`load::load` → `codegen::emit`), so a passing
//! vector is byte-identity against that CLI output; the root crate's
//! oracle suite is the per-commit tripwire for the pipeline itself,
//! and a codegen change that moves a golden fails this suite until
//! the goldens are regenerated with the recipe above. (Running the
//! CLI binary from this suite was rejected: the guest package does
//! not own the `surform` bin, so the test would depend on a
//! workspace-target path convention. Error goldens are generated from
//! the guest's own renderer; the CLI's stderr carries the same
//! per-diagnostic render — the piped theme is mirrored exactly.)
//!
//! The fixtures are the root crate's corpus (`tests/fixtures/`) —
//! self-contained documents only: `include` composition needs a
//! filesystem, which the Surrealism runtime does not grant the module
//! (no WASI preopens, probe-verified on 3.3 — that fail-closed path is
//! pinned live in the registration probe, not here — on the host
//! the loader WOULD resolve files, so an include fixture cannot pin
//! the in-guest behavior).

use std::fs;
use std::path::PathBuf;

use surform_surrealism::compile_sdl;

fn repo_file(rel: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join(rel);
    fs::read_to_string(&path)
        .unwrap_or_else(|err| panic!("corpus file {} unreadable: {err}", path.display()))
}

/// (fixture, expected-DDL golden) — every self-contained valid
/// document in the root corpus. `silo-module.surdl` is the dogfood
/// case: SDL that AUTHORS a module registration, compiled by the
/// module itself.
#[test]
fn ddl_is_byte_identical_to_the_cli_golden() {
    for (fixture, golden) in [
        ("clean.surdl", "clean.ddl"),
        ("app.surdl", "app.ddl"),
        ("raw.surdl", "raw.ddl"),
        ("silo-module.surdl", "silo-module.ddl"),
    ] {
        let sdl = repo_file(&format!("tests/fixtures/{fixture}"));
        let expected = repo_file(&format!("surform-surrealism/tests/goldens/{golden}"));
        let ddl = compile_sdl(&sdl)
            .unwrap_or_else(|err| panic!("{fixture}: unexpected rejection: {err}"));
        assert_eq!(ddl, expected, "{fixture}: DDL drifted from the CLI golden");
    }
}

/// The empty document compiles to empty DDL — the degenerate case the
/// CLI also accepts (pinned inline: there is no empty fixture).
#[test]
fn empty_document_compiles_to_empty_ddl() {
    assert_eq!(compile_sdl("").expect("empty SDL compiles"), "");
}

/// The migration snippet — the embeddable
/// `.surdl` the docs page ships ("Surform inside SurrealDB"). The
/// snippet is a FIRST-CLASS corpus document: it rides every compiler
/// change through this suite, the docgen build (its `sdl no-exec`
/// fence verifies parse + emit at build time), and the playground's
/// loader menu (parse-clean enforced there). Header-less by design
/// (the user appends it to their own schema, whose header names the
/// database — a header-less doc cannot be converge/apply's SDL
/// subject, refusing rather than migrating the wrong scope); the two
/// variants are the two artifacts' twins (`mod::surform` vs
/// `mod::surform_apply`, and `migrate` returning the script vs
/// applying in place). Goldens regenerated per the recipe above.
#[test]
fn the_migration_snippets_compile_to_the_cli_golden() {
    for (fixture, golden) in [
        ("docs/examples/surform-migrate.surdl", "surform-migrate.ddl"),
        (
            "docs/examples/surform-migrate-apply.surdl",
            "surform-migrate-apply.ddl",
        ),
    ] {
        let sdl = repo_file(fixture);
        let expected = repo_file(&format!("surform-surrealism/tests/goldens/{golden}"));
        let ddl = compile_sdl(&sdl)
            .unwrap_or_else(|err| panic!("{fixture}: unexpected rejection: {err}"));
        assert_eq!(ddl, expected, "{fixture}: DDL drifted from the CLI golden");
    }
}

/// The twin contract: the two
/// variants' shared wrappers are duplicated verbatim by the two-file
/// design — parameterization does not exist in SDL — and each
/// file's golden is independent, so a fix landing in one body and not
/// its twin stayed green everywhere. This test enforces it: identical wrapper name sets in order,
/// every shared body byte-equal modulo the module-path token
/// (`mod::surform_apply` → `mod::surform`), and the `migrate` bodies
/// differing exactly as documented (script-returning vs
/// apply-in-place).
#[test]
fn the_snippet_twins_shared_wrappers_differ_only_in_the_module_path() {
    // The `fn surform::NAME(…) … };` blocks in file order — comments
    // and blank lines sit between blocks, so a body is the block from
    // its `fn` line to the first column-0 `};`.
    fn extract(text: &str) -> Vec<(String, String)> {
        let mut blocks = Vec::new();
        let mut lines = text.lines();
        while let Some(line) = lines.next() {
            let Some(rest) = line.strip_prefix("fn surform::") else {
                continue;
            };
            let name = rest.split('(').next().unwrap_or_default().to_string();
            let mut body = format!("{line}\n");
            for inner in lines.by_ref() {
                body.push_str(inner);
                body.push('\n');
                if inner == "};" {
                    break;
                }
            }
            blocks.push((name, body));
        }
        blocks
    }
    let pure = extract(&repo_file("docs/examples/surform-migrate.surdl"));
    let apply = extract(&repo_file("docs/examples/surform-migrate-apply.surdl"));
    assert_eq!(
        pure.iter().map(|(name, _)| name).collect::<Vec<_>>(),
        apply.iter().map(|(name, _)| name).collect::<Vec<_>>(),
        "the twins' wrapper sets drifted (names or order)"
    );
    for ((name, pure_body), (_, apply_body)) in pure.iter().zip(&apply) {
        if name == "migrate" {
            assert!(
                pure_body.contains("fn::surform::converge($sdl)")
                    && !pure_body.contains("mod::surform"),
                "the pure twin's migrate stopped returning the script"
            );
            assert!(
                apply_body.contains("mod::surform_apply::apply($sdl)"),
                "the apply twin's migrate stopped applying in place"
            );
        } else {
            assert_eq!(
                apply_body.replace("mod::surform_apply", "mod::surform"),
                pure_body.as_str(),
                "{name}: the twins' shared wrapper bodies drifted apart"
            );
        }
    }
}

/// (fixture, expected-error golden) — the error taxonomy legs. Each
/// rejection is the stable prefix (the spike's proven
/// `SDL rejected: N diagnostics`, which the host surfaces verbatim
/// after `Function call error: `) plus the CLI-theme diagnostic
/// render. `broken.surdl` is a parse error with recovery in the same
/// document; `mixin-broken.surdl` is the mixin-lowering rejection
/// (SDL-E1061) — a different diagnostic family through the same
/// contract.
#[test]
fn rejections_carry_the_prefix_and_the_pinned_render() {
    for (fixture, golden) in [
        ("broken.surdl", "broken.err"),
        ("mixin-broken.surdl", "mixin-broken.err"),
    ] {
        let sdl = repo_file(&format!("tests/fixtures/{fixture}"));
        let expected = repo_file(&format!("surform-surrealism/tests/goldens/{golden}"));
        let err = compile_sdl(&sdl)
            .err()
            .unwrap_or_else(|| panic!("{fixture}: expected rejection"));
        assert!(
            err.starts_with("SDL rejected: "),
            "{fixture}: rejection lost the proven prefix: {err}"
        );
        assert_eq!(err, expected, "{fixture}: rejection render drifted");
    }
}

/// The prefix count is the diagnostic count (the spike's string
/// shape), asserted separately of the pinned renders.
#[test]
fn rejection_prefix_counts_the_diagnostics() {
    let sdl = repo_file("tests/fixtures/broken.surdl");
    let err = compile_sdl(&sdl).expect_err("broken.surdl rejects");
    let count = err
        .lines()
        .next()
        .unwrap_or_else(|| panic!("empty rejection"))
        .trim_start_matches("SDL rejected: ")
        .trim_end_matches(" diagnostics")
        .parse::<usize>()
        .expect("the prefix carries the count");
    assert_eq!(count, 1, "broken.surdl rejects with exactly one diagnostic");
    // The rendered diagnostics follow the prefix, one per line group.
    assert!(err.lines().count() > 1, "the render follows the prefix");
}
